using System.Collections.Generic;public class Solution{public IList<IList<int>> LevelOrderBottom(TreeNode r){var o=new List<IList<int>>();if(r==null)return o;var q=new Queue<TreeNode>();q.Enqueue(r);while(q.Count>0){int n=q.Count;var v=new List<int>();while(n-->0){var x=q.Dequeue();v.Add(x.val);if(x.left!=null)q.Enqueue(x.left);if(x.right!=null)q.Enqueue(x.right);}o.Insert(0,v);}return o;}}
